CREATE TABLE roles (name varchar(20) PRIMARY KEY CHECK(name IN ('STUDENT','STAFF','ADMIN')));
INSERT INTO roles VALUES ('STUDENT'),('STAFF'),('ADMIN');
CREATE TABLE departments (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(120) NOT NULL UNIQUE);
CREATE TABLE users (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(120) NOT NULL, email varchar(180) NOT NULL UNIQUE CHECK(email=lower(email)), password_hash varchar(100) NOT NULL, role varchar(20) NOT NULL REFERENCES roles(name), active boolean NOT NULL DEFAULT true, department_id bigint REFERENCES departments(id));
CREATE TABLE services (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(120) NOT NULL, code varchar(12) NOT NULL UNIQUE, description varchar(1000) NOT NULL, department_id bigint REFERENCES departments(id), active boolean NOT NULL DEFAULT true, appointment_enabled boolean NOT NULL DEFAULT true, walk_in_enabled boolean NOT NULL DEFAULT true, duration integer NOT NULL CHECK(duration BETWEEN 5 AND 180), slot_capacity integer NOT NULL CHECK(slot_capacity>0), appointment_capacity integer NOT NULL CHECK(appointment_capacity>0), walk_in_capacity integer NOT NULL CHECK(walk_in_capacity>0));
CREATE TABLE counters (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(120) NOT NULL UNIQUE, location varchar(200) NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE counter_services (counter_id bigint NOT NULL REFERENCES counters(id), service_id bigint NOT NULL REFERENCES services(id), PRIMARY KEY(counter_id,service_id));
CREATE TABLE staff_counters (counter_id bigint NOT NULL REFERENCES counters(id), user_id bigint NOT NULL REFERENCES users(id), PRIMARY KEY(counter_id,user_id));
CREATE TABLE working_hours (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, service_id bigint NOT NULL REFERENCES services(id), day_of_week integer NOT NULL CHECK(day_of_week BETWEEN 1 AND 7), opens time NOT NULL, closes time NOT NULL, break_start time, break_end time, UNIQUE(service_id,day_of_week), CHECK(opens<closes), CHECK((break_start IS NULL AND break_end IS NULL) OR (break_start IS NOT NULL AND break_end IS NOT NULL AND break_start>=opens AND break_end<=closes AND break_start<break_end)));
CREATE TABLE holidays (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, service_id bigint NOT NULL REFERENCES services(id), day date NOT NULL, name varchar(120) NOT NULL, UNIQUE(service_id,day));
CREATE TABLE service_days (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, service_id bigint NOT NULL REFERENCES services(id), day date NOT NULL, next_token integer NOT NULL DEFAULT 1, closed boolean NOT NULL DEFAULT false, UNIQUE(service_id,day));
CREATE TABLE appointment_slots (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, service_id bigint NOT NULL REFERENCES services(id), day date NOT NULL, starts time NOT NULL, ends time NOT NULL, capacity integer NOT NULL CHECK(capacity>0), UNIQUE(service_id,day,starts), CHECK(starts<ends));
CREATE TABLE appointments (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), service_id bigint NOT NULL REFERENCES services(id), slot_id bigint NOT NULL REFERENCES appointment_slots(id), day date NOT NULL, reference varchar(60) NOT NULL UNIQUE, status varchar(20) NOT NULL CHECK(status IN ('BOOKED','CHECKED_IN','COMPLETED','CANCELLED','NO_SHOW','SKIPPED')), created_at timestamptz NOT NULL, completed_at timestamptz);
CREATE UNIQUE INDEX one_active_appointment ON appointments(user_id,service_id,day) WHERE status IN ('BOOKED','CHECKED_IN');
CREATE TABLE queue_entries (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), service_id bigint NOT NULL REFERENCES services(id), appointment_id bigint UNIQUE REFERENCES appointments(id), day date NOT NULL, token varchar(30) NOT NULL, status varchar(20) NOT NULL CHECK(status IN ('WAITING','CALLED','SERVING','COMPLETED','SKIPPED','HOLD')), counter_id bigint REFERENCES counters(id), staff_id bigint REFERENCES users(id), joined_at timestamptz NOT NULL, queued_at timestamptz NOT NULL, called_at timestamptz, started_at timestamptz, completed_at timestamptz, reason varchar(500), UNIQUE(service_id,day,token), CHECK(status NOT IN ('CALLED','SERVING') OR (counter_id IS NOT NULL AND staff_id IS NOT NULL)));
CREATE UNIQUE INDEX one_active_counter ON queue_entries(counter_id) WHERE status IN ('CALLED','SERVING');
CREATE UNIQUE INDEX one_active_queue ON queue_entries(user_id,service_id,day) WHERE status IN ('WAITING','CALLED','SERVING','HOLD');
CREATE INDEX queue_selection ON queue_entries(day,status,queued_at,id);
CREATE INDEX queue_service_day ON queue_entries(service_id,day,status);
CREATE INDEX appointment_history ON appointments(user_id,day);
CREATE INDEX appointment_capacity ON appointments(slot_id,status);
CREATE TABLE notifications (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), message varchar(1000) NOT NULL, seen boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL);
CREATE TABLE audit_logs (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id bigint REFERENCES users(id), action varchar(80) NOT NULL, details varchar(1000) NOT NULL, created_at timestamptz NOT NULL);
CREATE INDEX notification_recipient ON notifications(user_id,created_at);
